{
  "Comment": "Gold Layer - Single job processing + crawler (Fixed context management)",
  "StartAt": "SetupGoldVariables",
  "States": {
    "SetupGoldVariables": {
      "Type": "Pass",
      "Comment": "Setup shared variables for Gold processing",
      "Parameters": {
        "job_process_id.$": "$$.Execution.Name",
        "dynamic_job_name.$": "States.Format('datalake-dev-clientes-gold_{}', $$.Execution.Name)",
        "execution_metadata": {
          "test_name.$": "$.test_id",
          "environment.$": "$.environment",
          "description.$": "$.description",
          "executed_by.$": "$.executed_by"
        },
        "gold_config": {
          "BUCKET_GOLD": "alfa-datalake-dev-gold",
          "BUCKET_SILVER": "alfa-datalake-dev-silver",
          "S3_GOLD_CONFIG_PATH": "s3://alfa-datalake-dev-clientes-assets/phase_gold/config/gold_config-facts.json",
          "DELTA_SPARK_CONF": "spark.sql.extensions=io.delta.sql.DeltaSparkSessionExtension --conf spark.sql.catalog.spark_catalog=org.apache.spark.sql.delta.catalog.DeltaCatalog --conf spark.delta.logStore.class=org.apache.spark.sql.delta.storage.S3SingleDriverLogStore",
          "DATALAKE_FORMATS": "delta"
        }
      },
      "Next": "DatalakeClientsGold"
    },
    "DatalakeClientsGold": {
      "Type": "Task",
      "Resource": "arn:aws:states:::glue:startJobRun.sync",
      "Comment": "Execute Gold layer processing job",
      "Parameters": {
        "JobName": "datalake-dev-clientes-gold",
        "Arguments": {
          "--JOB_NAME.$": "$.dynamic_job_name",
          "--JOB_PROCESS_ID.$": "$.job_process_id",
          "--BUCKET_GOLD.$": "$.gold_config.BUCKET_GOLD",
          "--BUCKET_SILVER.$": "$.gold_config.BUCKET_SILVER",
          "--S3_GOLD_CONFIG_PATH.$": "$.gold_config.S3_GOLD_CONFIG_PATH",
          "--conf.$": "$.gold_config.DELTA_SPARK_CONF",
          "--datalake-formats.$": "$.gold_config.DATALAKE_FORMATS"
        }
      },
      "ResultPath": "$.gold_job_result",
      "Next": "ProcessGoldResults"
    },
    "ProcessGoldResults": {
      "Type": "Pass",
      "Comment": "Process results from Gold job and preserve context",
      "Parameters": {
        "job_execution_summary": {
          "job_name.$": "$.dynamic_job_name",
          "job_process_id.$": "$.job_process_id",
          "completion_time.$": "$$.State.EnteredTime",
          "job_result.$": "$.gold_job_result"
        },
        "execution_metadata.$": "$.execution_metadata",
        "gold_config.$": "$.gold_config"
      },
      "Next": "ExecuteGoldCrawler"
    },
    "ExecuteGoldCrawler": {
      "Type": "Task",
      "Resource": "arn:aws:states:::aws-sdk:glue:startCrawler",
      "Comment": "Execute Gold crawler to update catalog",
      "Parameters": {
        "Name": "datalake-dev-clientes-gold"
      },
      "ResultPath": "$.crawler_start_result",
      "Next": "WaitForGoldCrawler"
    },
    "WaitForGoldCrawler": {
      "Type": "Task",
      "Resource": "arn:aws:states:::aws-sdk:glue:getCrawler",
      "Comment": "Check Gold crawler status",
      "Parameters": {
        "Name": "datalake-dev-clientes-gold"
      },
      "ResultPath": "$.crawler_status",
      "Next": "CheckGoldCrawlerStatus"
    },
    "CheckGoldCrawlerStatus": {
      "Type": "Choice",
      "Comment": "Check if Gold crawler finished",
      "Choices": [
        {
          "Variable": "$.crawler_status.Crawler.State",
          "StringEquals": "READY",
          "Next": "GoldCrawlerSuccess"
        },
        {
          "Variable": "$.crawler_status.Crawler.State",
          "StringEquals": "STOPPING",
          "Next": "GoldCrawlerSuccess"
        },
        {
          "Variable": "$.crawler_status.Crawler.State",
          "StringEquals": "RUNNING",
          "Next": "WaitForGoldCrawlerCompletion"
        }
      ],
      "Default": "GoldCrawlerFailed"
    },
    "WaitForGoldCrawlerCompletion": {
      "Type": "Wait",
      "Comment": "Wait 30 seconds before checking crawler again",
      "Seconds": 30,
      "Next": "WaitForGoldCrawler"
    },
    "GoldCrawlerSuccess": {
      "Type": "Pass",
      "Comment": "Gold crawler completed successfully",
      "Parameters": {
        "final_status": "SUCCESS",
        "message": "Gold processing pipeline completed successfully",
        "execution_details": {
          "job_name.$": "$.job_execution_summary.job_name",
          "job_process_id.$": "$.job_execution_summary.job_process_id",
          "crawler_completion_time.$": "$$.State.EnteredTime",
          "job_completion_time.$": "$.job_execution_summary.completion_time"
        },
        "crawler_info": {
          "name": "datalake-dev-clientes-gold",
          "status": "COMPLETED",
          "final_state.$": "$.crawler_status.Crawler.State",
          "last_crawl.$": "$.crawler_status.Crawler.LastCrawl"
        },
        "execution_metadata.$": "$.execution_metadata"
      },
      "Next": "Success"
    },
    "GoldCrawlerFailed": {
      "Type": "Pass",
      "Comment": "Gold crawler execution failed - capture error details",
      "Parameters": {
        "final_status": "FAILED",
        "message": "Gold crawler execution failed",
        "error_details": {
          "crawler_state.$": "$.crawler_status.Crawler.State",
          "last_crawl.$": "$.crawler_status.Crawler.LastCrawl",
          "job_name.$": "$.job_execution_summary.job_name",
          "job_process_id.$": "$.job_execution_summary.job_process_id"
        }
      },
      "Next": "Fail"
    },
    "Fail": {
      "Type": "Fail",
      "Comment": "Pipeline execution failed",
      "Cause": "Gold crawler did not complete successfully"
    },
    "Success": {
      "Type": "Succeed",
      "Comment": "Complete Gold workflow finished successfully"
    }
  }
}
